type GitRunStatus uint8

const (
	GitRunStatus_Ok             GitRunStatus = 0
	GitRunStatus_RepoNotAllowed GitRunStatus = 1
	GitRunStatus_NoSource       GitRunStatus = 2
	GitRunStatus_NotAGitRepo    GitRunStatus = 3
	GitRunStatus_BadRev         GitRunStatus = 4
	GitRunStatus_GitFailed      GitRunStatus = 5
	GitRunStatus_IoError        GitRunStatus = 6
	GitRunStatus_SubrepoInvalid GitRunStatus = 7
	GitRunStatus_FileNotFound   GitRunStatus = 8
)

func (e GitRunStatus) String() string {
	switch e {
	case GitRunStatus_Ok:
		return "ok"
	case GitRunStatus_RepoNotAllowed:
		return "repo_not_allowed"
	case GitRunStatus_NoSource:
		return "no_source"
	case GitRunStatus_NotAGitRepo:
		return "not_a_git_repo"
	case GitRunStatus_BadRev:
		return "bad_rev"
	case GitRunStatus_GitFailed:
		return "git_failed"
	case GitRunStatus_IoError:
		return "io_error"
	case GitRunStatus_SubrepoInvalid:
		return "subrepo_invalid"
	case GitRunStatus_FileNotFound:
		return "file_not_found"
	default:
		return fmt.Sprintf("GitRunStatus(%d)", e)
	}
}

